#!/usr/bin/env python
"""
01_train_CellFM.py - prepare inputs and train CellFM for NOCAP benchmarking

This release-facing entry point integrates CellFM checkpoint adaptation, control-cell
embedding extraction, GO graph preparation, and CellFM-GEARS training.
"""

import argparse
import sys

STAGE_SOURCES = {'adapt_checkpoint': '"""\ncheckpoint adaptation stage - Dataset Adaptation (Optional Step 0)\n\nThis script follows the ORIGINAL CellFM approach for "dataset adaptation":\n1. Load pretrained CellFM model\n2. Finetune on ALL cells in the dataset (no perturbation split!)\n3. Use masked expression prediction (like MLM)\n4. Save adapted checkpoint\n\nThis is DIFFERENT from perturbation-specific finetuning:\n- Dataset adaptation: Adapts to gene expression distribution of the dataset\n- Perturbation finetuning: Learns perturbation-specific patterns\n\nThe key insight: Dataset adaptation uses ALL cells including controls,\nso there\'s no train/test split mismatch problem when combined with GEARS.\n\nUsage:\n    python checkpoint adaptation stage \\\n        --data_path /path/to/perturbation_data.h5ad \\\n        --ckpt_path models/CellFM_80M/CellFM_80M_weight.ckpt \\\n        --output_dir adapted_models/norman \\\n        --epochs 5 \\\n        --device cuda:0\n\nReference from CellFM GitHub:\n    python train.py --data NOCAP_perturbation --load_pretrain --epoch 5 --batch 4\n"""\n\nimport os\nimport sys\nimport argparse\nimport numpy as np\nimport torch\nimport torch.nn as nn\nfrom torch.optim import AdamW\nfrom torch.cuda.amp import GradScaler\nfrom pathlib import Path\nfrom tqdm import tqdm\n\n# Add parent directory to path\nCODES_DIR = os.path.dirname(os.path.abspath(__file__))\nROOT_DIR = os.path.dirname(CODES_DIR)\nCODES_V1_DIR = os.path.join(ROOT_DIR, \'codes\')\nsys.path.insert(0, ROOT_DIR)\nsys.path.insert(0, CODES_V1_DIR)\n\nfrom model import Finetune_Cell_FM\nfrom layers.utils import Config_80M, read_h5ad, SCrna, Prepare, build_dataset\n\n\ndef parse_args():\n    parser = argparse.ArgumentParser(description=\'CellFM Dataset Adaptation (Original Approach)\')\n\n    # Data paths\n    parser.add_argument(\'--data_path\', type=str, required=True,\n                        help=\'Path to h5ad data file\')\n    parser.add_argument(\'--ckpt_path\', type=str, required=True,\n                        help=\'Path to pretrained CellFM checkpoint\')\n    parser.add_argument(\'--output_dir\', type=str, required=True,\n                        help=\'Output directory for adapted model\')\n\n    # Training parameters\n    parser.add_argument(\'--epochs\', type=int, default=5,\n                        help=\'Number of epochs (default: 5)\')\n    parser.add_argument(\'--batch_size\', type=int, default=4,\n                        help=\'Batch size (default: 4)\')\n    parser.add_argument(\'--lr\', type=float, default=1e-5,\n                        help=\'Learning rate (default: 1e-5)\')\n    parser.add_argument(\'--mask_ratio\', type=float, default=0.2,\n                        help=\'Mask ratio for MLM (default: 0.2)\')\n\n    # Model parameters\n    parser.add_argument(\'--max_seq_len\', type=int, default=2048,\n                        help=\'Maximum sequence length (default: 2048)\')\n\n    # Seed for reproducibility (fixed at 42, shared across all GEARS seeds)\n    parser.add_argument(\'--seed\', type=int, default=42,\n                        help=\'Random seed (default: 42, fixed for adaptation)\')\n\n    # Device\n    parser.add_argument(\'--device\', type=str, default=\'cuda:0\',\n                        help=\'Device to use (default: cuda:0)\')\n\n    return parser.parse_args()\n\n\ndef ensure_columns(adata):\n    """Ensure required columns exist in adata.obs."""\n    # Add celltype column if missing (required by SCrna)\n    if \'celltype\' not in adata.obs.columns:\n        if \'cell_type\' in adata.obs.columns:\n            adata.obs[\'celltype\'] = adata.obs[\'cell_type\'].astype(str)\n        else:\n            adata.obs[\'celltype\'] = \'unknown\'\n\n    # Add feat column (cell type codes)\n    if \'feat\' not in adata.obs.columns:\n        cat = adata.obs[\'celltype\'].astype(\'category\')\n        adata.obs[\'feat\'] = cat.cat.codes.astype(np.int64)\n\n    # For dataset adaptation, we use ALL cells (no split)\n    # Set all cells to train (mode=0)\n    adata.obs[\'train\'] = 0\n\n    # Add batch_id if missing\n    if \'batch_id\' not in adata.obs.columns:\n        adata.obs[\'batch_id\'] = 0\n\n    # Count unique cell types for classifier (even though we don\'t use it)\n    num_cls = len(adata.obs[\'celltype\'].unique())\n\n    return adata, num_cls\n\n\ndef build_train_loader(adata, cfg, batch_size):\n    """Build data loader for ALL cells (no split)."""\n    # Change to ROOT_DIR since SCrna uses relative paths (csv/expand_gene_info.csv)\n    original_dir = os.getcwd()\n    os.chdir(ROOT_DIR)\n    try:\n        dataset = SCrna(adata, mode="train")  # mode=train gets all cells with train=0\n        prep = Prepare(cfg.nonz_len, pad=0, mask_ratio=cfg.mask_ratio, cut=cfg.nonz_len)\n        loader = build_dataset(\n            dataset,\n            prep=prep,\n            batch_size=batch_size,\n            pad_zero=cfg.pad_zero,\n            drop=False,\n            shuffle=True,\n        )\n    finally:\n        os.chdir(original_dir)\n    return loader\n\n\ndef train_epoch(net, loader, optimizer, scaler, device, max_grad_norm=0.5):\n    """Train one epoch with masked expression prediction."""\n    net.train()\n    running_loss = 0.0\n    nan_count = 0\n\n    progress = tqdm(loader, desc="Training", leave=False)\n    for step, batch in enumerate(progress):\n        raw_nzdata = batch["raw_nzdata"].to(device)\n        dw_nzdata = batch["dw_nzdata"].to(device)\n        ST_feat = batch["ST_feat"].to(device)\n        nonz_gene = batch["nonz_gene"].to(device)\n        mask_gene = batch["mask_gene"].to(device)\n        zero_idx = batch["zero_idx"].to(device)\n\n        optimizer.zero_grad()\n\n        with torch.cuda.amp.autocast():\n            _, mask_loss, _ = net(\n                raw_nzdata=raw_nzdata,\n                dw_nzdata=dw_nzdata,\n                ST_feat=ST_feat,\n                nonz_gene=nonz_gene,\n                mask_gene=mask_gene,\n                zero_idx=zero_idx,\n            )\n            # Only mask_loss (MSE for masked gene expression prediction)\n            loss = mask_loss\n\n        # NaN detection\n        if torch.isnan(loss) or torch.isinf(loss):\n            nan_count += 1\n            continue\n\n        scaler.scale(loss).backward()\n        scaler.unscale_(optimizer)\n        nn.utils.clip_grad_norm_(net.parameters(), max_norm=max_grad_norm)\n        scaler.step(optimizer)\n        scaler.update()\n\n        running_loss += loss.item()\n        progress.set_postfix(loss=running_loss / (step + 1 - nan_count))\n\n    avg_loss = running_loss / max(len(loader) - nan_count, 1)\n    return avg_loss, nan_count\n\n\ndef main():\n    args = parse_args()\n\n    # Set random seeds for reproducibility\n    np.random.seed(args.seed)\n    torch.manual_seed(args.seed)\n    if torch.cuda.is_available():\n        torch.cuda.manual_seed(args.seed)\n        torch.cuda.manual_seed_all(args.seed)\n    torch.backends.cudnn.deterministic = True\n    torch.backends.cudnn.benchmark = False\n\n    print("=" * 70)\n    print("CellFM Dataset Adaptation (Original CellFM Approach)")\n    print("=" * 70)\n    print(f"Data path: {args.data_path}")\n    print(f"Checkpoint: {args.ckpt_path}")\n    print(f"Output: {args.output_dir}")\n    print(f"Seed: {args.seed}")\n    print(f"Epochs: {args.epochs}")\n    print(f"Batch size: {args.batch_size}")\n    print(f"Learning rate: {args.lr}")\n    print(f"Mask ratio: {args.mask_ratio}")\n    print(f"Device: {args.device}")\n    print("=" * 70)\n    print("\\nNOTE: This adapts the model to the dataset\'s gene expression")\n    print("distribution using ALL cells (no perturbation split).")\n    print("=" * 70)\n\n    # Create output directory\n    output_dir = Path(args.output_dir)\n    output_dir.mkdir(parents=True, exist_ok=True)\n\n    # Setup config\n    cfg = Config_80M()\n    cfg.ecs_threshold = 0.8\n    cfg.ecs = True\n    cfg.add_zero = True\n    cfg.pad_zero = True\n    cfg.mask_ratio = args.mask_ratio\n    cfg.nonz_len = args.max_seq_len\n    cfg.mask_len = args.max_seq_len\n    cfg.ckpt_path = args.ckpt_path\n    cfg.device = args.device\n\n    # Load data\n    print("\\n[1/4] Loading data...")\n    adata = read_h5ad(args.data_path)\n    adata, num_cls = ensure_columns(adata)\n    cfg.num_cls = num_cls\n\n    print(f"  Total cells: {adata.n_obs}")\n    print(f"  Total genes: {adata.n_vars}")\n    print(f"  Cell types: {num_cls}")\n\n    # Build data loader (ALL cells, no split)\n    print("\\n[2/4] Building data loader...")\n    train_loader = build_train_loader(adata, cfg, args.batch_size)\n    print(f"  Batches per epoch: {len(train_loader)}")\n\n    # Initialize model\n    print("\\n[3/4] Initializing model...")\n    device = torch.device(args.device if torch.cuda.is_available() else \'cpu\')\n    net = Finetune_Cell_FM(cfg).to(device)\n\n    # Freeze non-encoder parts, only train encoder\n    for name, param in net.named_parameters():\n        param.requires_grad = "encoder" in name\n\n    trainable_params = sum(p.numel() for p in net.parameters() if p.requires_grad)\n    total_params = sum(p.numel() for p in net.parameters())\n    print(f"  Total parameters: {total_params:,}")\n    print(f"  Trainable parameters: {trainable_params:,}")\n\n    # Load pretrained weights\n    print(f"\\n  Loading pretrained weights from: {args.ckpt_path}")\n    net.extractor.load_model(weight=True, moment=False)\n\n    # Setup optimizer\n    optimizer = AdamW(\n        [p for p in net.parameters() if p.requires_grad],\n        lr=args.lr,\n        weight_decay=1e-5,\n    )\n    scaler = GradScaler()\n    scheduler = torch.optim.lr_scheduler.StepLR(optimizer, step_size=1, gamma=0.9)\n\n    # Training loop\n    print("\\n[4/4] Training (Dataset Adaptation)...")\n    best_loss = float(\'inf\')\n    best_epoch = 0\n\n    for epoch in range(1, args.epochs + 1):\n        print(f"\\nEpoch {epoch}/{args.epochs}")\n\n        train_loss, nan_count = train_epoch(\n            net, train_loader, optimizer, scaler, device\n        )\n        scheduler.step()\n\n        print(f"  Loss: {train_loss:.6f} (NaN batches: {nan_count})")\n\n        # Save checkpoint\n        ckpt_path = output_dir / f"checkpoint_epoch_{epoch}.pth"\n        torch.save(net.state_dict(), ckpt_path)\n\n        if train_loss < best_loss:\n            best_loss = train_loss\n            best_epoch = epoch\n            torch.save(net.state_dict(), output_dir / "best_checkpoint.pth")\n            print(f"  [BEST] New best model saved")\n\n    # Save final model\n    torch.save(net.state_dict(), output_dir / "final_checkpoint.pth")\n\n    print("\\n" + "=" * 70)\n    print("Dataset Adaptation Complete!")\n    print("=" * 70)\n    print(f"Best epoch: {best_epoch}")\n    print(f"Best loss: {best_loss:.6f}")\n    print(f"Checkpoints saved to: {output_dir}")\n    print(f"  - best_checkpoint.pth (use this for embedding extraction)")\n    print(f"  - final_checkpoint.pth")\n\n    # Save config for reference\n    config_info = {\n        \'data_path\': args.data_path,\n        \'ckpt_path\': args.ckpt_path,\n        \'epochs\': args.epochs,\n        \'batch_size\': args.batch_size,\n        \'lr\': args.lr,\n        \'mask_ratio\': args.mask_ratio,\n        \'max_seq_len\': args.max_seq_len,\n        \'n_cells\': adata.n_obs,\n        \'n_genes\': adata.n_vars,\n        \'best_epoch\': best_epoch,\n        \'best_loss\': best_loss,\n    }\n    import json\n    with open(output_dir / \'training_config.json\', \'w\') as f:\n        json.dump(config_info, f, indent=2)\n\n\nif __name__ == \'__main__\':\n    main()\n', 'extract_embeddings': '"""\n01_extract_ctrl_embeddings.py - Extract cell-level embeddings from control cells\n\nThis script follows the ORIGINAL CellFM approach:\n1. Load adapted CellFM model (.pth format only)\n2. Pass ONLY control cells through the encoder\n3. Extract cell-level embeddings (n_ctrl_cells, n_genes, hidden_dim)\n4. Save for use in GEARS\n\nThis avoids the train/test split problem because control cells\nare shared across all perturbation splits.\n\nMEMORY-MAPPED SAVING (v19):\n    The script uses memory-mapped arrays to write embeddings directly to disk,\n    avoiding RAM accumulation that caused OOM crashes. This allows extraction\n    of all 10,000 control cells (~111 GB output) with only ~5-8 GB RAM usage.\n\n    Previous approach: Accumulated all embeddings in RAM → 1.1 TB → OOM → server crash\n    New approach: Write each batch to disk immediately → ~5 GB RAM → stable\n\nNOTE: MindSpore .ckpt files are NOT supported. Run 01_train_CellFM.py [checkpoint-adaptation stage] first\nto convert and adapt the model to .pth format.\n\nUsage:\n    python 01_extract_ctrl_embeddings.py \\\n        --data_path /path/to/perturbation_data.h5ad \\\n        --ckpt_path /path/to/adapted_checkpoint.pth \\\n        --output_path embeddings/cellfm_ctrl_emb.npy \\\n        --device cuda:0\n\nOutput:\n    - embeddings/cellfm_ctrl_emb.npy: (n_ctrl_cells, n_genes, 1536) - memory-mapped format\n    - embeddings/cellfm_ctrl_emb_meta.npz: metadata file\n"""\n\nimport os\nimport sys\nimport argparse\nimport numpy as np\nimport torch\nfrom tqdm import tqdm\nimport scanpy as sc\n\n# Add root directory to path\nCODES_DIR = os.path.dirname(os.path.abspath(__file__))\nROOT_DIR = os.path.dirname(CODES_DIR)\nsys.path.insert(0, ROOT_DIR)\n\nfrom layers.torch_finetune import FinetuneModel\nfrom layers.utils import Config_80M\n\n\ndef parse_args():\n    parser = argparse.ArgumentParser(description=\'Extract control cell embeddings from CellFM\')\n    parser.add_argument(\'--data_path\', type=str, required=True,\n                        help=\'Path to h5ad data file\')\n    parser.add_argument(\'--ckpt_path\', type=str, required=True,\n                        help=\'Path to CellFM checkpoint (.ckpt or .pth)\')\n    parser.add_argument(\'--output_path\', type=str, required=True,\n                        help=\'Output path for embeddings .npy file\')\n    parser.add_argument(\'--control_col\', type=str, default=\'condition\',\n                        help=\'Column name for condition labels (default: condition)\')\n    parser.add_argument(\'--control_label\', type=str, default=\'ctrl\',\n                        help=\'Label for control cells (default: ctrl)\')\n    parser.add_argument(\'--batch_size\', type=int, default=32,\n                        help=\'Batch size for inference (default: 32)\')\n    parser.add_argument(\'--device\', type=str, default=\'cuda:0\',\n                        help=\'Device to use (default: cuda:0)\')\n    parser.add_argument(\'--max_cells\', type=int, default=None,\n                        help=\'Maximum number of control cells to use (default: all)\')\n    parser.add_argument(\'--seed\', type=int, default=42,\n                        help=\'Random seed for subsampling (default: 42, fixed for extraction)\')\n    return parser.parse_args()\n\n\ndef load_model(ckpt_path, n_genes, device):\n    """Load CellFM model from checkpoint."""\n    print(f"Loading model from: {ckpt_path}")\n\n    # Setup config\n    cfg = Config_80M()\n    cfg.enc_dims = 1536\n    cfg.enc_nlayers = 2  # Will be overridden by checkpoint\n    cfg.enc_num_heads = 48\n    cfg.add_zero = False\n    cfg.pad_zero = True\n    cfg.ecs = False\n    cfg.ecs_threshold = 0.8\n    cfg.lora = 0\n    cfg.recompute = False\n    cfg.dropout = 0.1\n\n    # Create model\n    model = FinetuneModel(n_genes, cfg)\n\n    # Load PyTorch checkpoint (.pth only - MindSpore .ckpt not supported)\n    if ckpt_path.endswith(\'.ckpt\'):\n        raise ValueError(\n            f"MindSpore .ckpt files not supported. "\n            f"Use 01_train_CellFM.py [checkpoint-adaptation stage] to convert to .pth first, or use an already adapted checkpoint."\n        )\n\n    state_dict = torch.load(ckpt_path, map_location=\'cpu\', weights_only=False)\n\n    # Handle wrapped model state dict (from adaptation training)\n    if any(k.startswith(\'extractor.net.\') for k in state_dict.keys()):\n        new_state_dict = {}\n        for k, v in state_dict.items():\n            if k.startswith(\'extractor.net.\'):\n                new_state_dict[k.replace(\'extractor.net.\', \'\')] = v\n        state_dict = new_state_dict\n\n    missing, unexpected = model.load_state_dict(state_dict, strict=False)\n    print(f"  Missing keys: {len(missing)}")\n    print(f"  Unexpected keys: {len(unexpected)}")\n\n    model = model.to(device)\n    model.eval()\n    return model, cfg\n\n\ndef prepare_cell_input(expr_data, gene_indices, device):\n    """Prepare cell expression data for model input.\n\n    Args:\n        expr_data: numpy array of shape (batch, n_genes) - normalized expression\n        gene_indices: gene indices for the model\n        device: torch device\n\n    Returns:\n        expr, gene, zero_idx tensors ready for model\n    """\n    batch_size, n_genes = expr_data.shape\n\n    # Expression tensor\n    expr = torch.tensor(expr_data, dtype=torch.float32, device=device)\n\n    # Gene indices (same for all cells)\n    gene = torch.tensor(gene_indices, dtype=torch.long, device=device)\n    gene = gene.unsqueeze(0).expand(batch_size, -1)\n\n    # Zero mask (1 where expression > 0)\n    zero_idx = (expr > 0).float()\n\n    return expr, gene, zero_idx\n\n\ndef extract_embeddings(model, adata_ctrl, gene_indices, batch_size, device, output_path):\n    """Extract embeddings from control cells using memory-mapped saving.\n\n    This avoids OOM by writing directly to disk instead of accumulating in RAM.\n    Memory usage stays constant (~5-8 GB) regardless of number of cells.\n    """\n    n_cells = adata_ctrl.n_obs\n    n_genes = len(gene_indices)\n    hidden_dim = 1536\n\n    print(f"Extracting embeddings from {n_cells} control cells...")\n    print(f"  Output shape: ({n_cells}, {n_genes}, {hidden_dim})")\n\n    # Calculate output file size\n    file_size_gb = (n_cells * n_genes * hidden_dim * 4) / (1024**3)\n    print(f"  Output file size: {file_size_gb:.1f} GB")\n\n    # Get expression matrix\n    if hasattr(adata_ctrl.X, \'toarray\'):\n        X = adata_ctrl.X.toarray()\n    else:\n        X = np.array(adata_ctrl.X)\n\n    # Normalize if needed (log1p)\n    if X.max() > 100:\n        print("  Applying log1p normalization...")\n        X = np.log1p(X)\n\n    # Create output directory if needed\n    output_dir = os.path.dirname(output_path)\n    if output_dir:\n        os.makedirs(output_dir, exist_ok=True)\n\n    # Create memory-mapped file for output\n    # This writes directly to disk, avoiding RAM accumulation\n    print(f"  Creating memory-mapped output file...")\n    embeddings_mmap = np.memmap(\n        output_path,\n        dtype=\'float32\',\n        mode=\'w+\',\n        shape=(n_cells, n_genes, hidden_dim)\n    )\n\n    with torch.no_grad():\n        for i in tqdm(range(0, n_cells, batch_size), desc="Extracting"):\n            batch_expr = X[i:i+batch_size]\n            actual_batch_size = batch_expr.shape[0]\n\n            # Prepare input\n            expr, gene, zero_idx = prepare_cell_input(batch_expr, gene_indices, device)\n\n            # Forward pass through encoder\n            # embedding_infer returns (expr_emb, gene_emb)\n            # expr_emb shape: (batch, n_genes+1, hidden_dim) with CLS token\n            expr_emb, _ = model.embedding_infer(expr, gene, ST_feat=None, zero_idx=zero_idx)\n\n            # Remove CLS token (first position)\n            expr_emb = expr_emb[:, 1:, :]  # (batch, n_genes, hidden_dim)\n\n            # Write directly to memory-mapped file (disk)\n            embeddings_mmap[i:i+actual_batch_size] = expr_emb.cpu().numpy()\n\n    # Flush to ensure all data is written to disk\n    embeddings_mmap.flush()\n\n    print(f"  Final embeddings shape: {embeddings_mmap.shape}")\n    print(f"  Embeddings saved to: {output_path}")\n\n    # Return shape info (not the array itself to save memory)\n    return embeddings_mmap.shape\n\n\ndef main():\n    args = parse_args()\n\n    print("=" * 60)\n    print("CellFM Control Cell Embedding Extraction (Original Method)")\n    print("=" * 60)\n    print(f"Data path: {args.data_path}")\n    print(f"Checkpoint: {args.ckpt_path}")\n    print(f"Output: {args.output_path}")\n    print(f"Control column: {args.control_col}")\n    print(f"Control label: {args.control_label}")\n    print(f"Batch size: {args.batch_size}")\n    print(f"Device: {args.device}")\n    print("=" * 60)\n\n    # Load data\n    print("\\n[1/4] Loading data...")\n    adata = sc.read_h5ad(args.data_path)\n    print(f"  Total cells: {adata.n_obs}")\n    print(f"  Total genes: {adata.n_vars}")\n\n    # Filter control cells\n    print("\\n[2/4] Filtering control cells...")\n    if args.control_col not in adata.obs.columns:\n        # Try alternative column names\n        alt_cols = [\'condition\', \'perturbation\', \'target_gene\']\n        for col in alt_cols:\n            if col in adata.obs.columns:\n                args.control_col = col\n                break\n\n    # Find control cells\n    if args.control_col in adata.obs.columns:\n        ctrl_mask = adata.obs[args.control_col] == args.control_label\n        if ctrl_mask.sum() == 0:\n            # Try alternative control labels\n            alt_labels = [\'ctrl\', \'control\', \'non-targeting\', \'CTRL\']\n            for label in alt_labels:\n                ctrl_mask = adata.obs[args.control_col] == label\n                if ctrl_mask.sum() > 0:\n                    args.control_label = label\n                    break\n    else:\n        raise ValueError(f"Control column \'{args.control_col}\' not found in adata.obs")\n\n    adata_ctrl = adata[ctrl_mask]\n    print(f"  Control cells found: {adata_ctrl.n_obs}")\n\n    if args.max_cells and adata_ctrl.n_obs > args.max_cells:\n        print(f"  Subsampling to {args.max_cells} cells (seed={args.seed})...")\n        np.random.seed(args.seed)\n        indices = np.random.choice(adata_ctrl.n_obs, args.max_cells, replace=False)\n        adata_ctrl = adata_ctrl[indices]\n\n    # Prepare gene indices\n    print("\\n[3/4] Preparing gene mapping...")\n    import pandas as pd\n    gene_info_path = os.path.join(ROOT_DIR, \'csv\', \'expand_gene_info.csv\')\n    if os.path.exists(gene_info_path):\n        gene_info = pd.read_csv(gene_info_path, index_col=0)\n        geneset = {j: i + 1 for i, j in enumerate(gene_info.index)}\n    else:\n        # Fallback to new_gene_info.csv\n        gene_info_path = os.path.join(ROOT_DIR, \'csv\', \'new_gene_info.csv\')\n        gene_info = pd.read_csv(gene_info_path, index_col=0)\n        geneset = {j: i + 1 for i, j in enumerate(gene_info.index)}\n\n    # Map genes\n    gene_indices = np.array([geneset.get(g, 0) for g in adata_ctrl.var_names]).astype(np.int32)\n    n_mapped = (gene_indices > 0).sum()\n    print(f"  Genes mapped: {n_mapped}/{len(gene_indices)}")\n\n    # Load model\n    print("\\n[4/4] Loading model and extracting embeddings...")\n    device = torch.device(args.device if torch.cuda.is_available() else \'cpu\')\n    n_genes_vocab = len(geneset)  # 27855, matching hardcoded value in model.py\n    model, cfg = load_model(args.ckpt_path, n_genes_vocab, device)\n\n    # Extract embeddings (saves directly to disk via memory-mapping)\n    emb_shape = extract_embeddings(\n        model, adata_ctrl, gene_indices,\n        args.batch_size, device, args.output_path\n    )\n\n    print("\\n" + "=" * 60)\n    print("Extraction Complete!")\n    print("=" * 60)\n    print(f"Output: {args.output_path}")\n    print(f"Shape: {emb_shape}")\n    print(f"  - {emb_shape[0]} control cells")\n    print(f"  - {emb_shape[1]} genes")\n    print(f"  - {emb_shape[2]} embedding dimensions")\n\n    file_size = os.path.getsize(args.output_path) / (1024 * 1024 * 1024)\n    print(f"File size: {file_size:.1f} GB")\n\n    # Save metadata\n    meta_path = args.output_path.replace(\'.npy\', \'_meta.npz\')\n    np.savez(meta_path,\n             n_cells=emb_shape[0],\n             n_genes=emb_shape[1],\n             hidden_dim=emb_shape[2],\n             control_col=args.control_col,\n             control_label=args.control_label,\n             gene_indices=gene_indices)\n    print(f"Metadata saved to: {meta_path}")\n\n\nif __name__ == \'__main__\':\n    main()\n', 'generate_go_graph': '"""\nGenerate a filtered GO graph for nocap_perturbation dataset.\n\nThis script creates a smaller, usable go.csv by:\n1. Restricting to genes present in perturb_processed.h5ad (19,424 genes)\n2. Applying top-k filtering (keep only k most similar neighbors per gene)\n\nThis matches the approach used for the Norman dataset, which has ~674K edges\ninstead of the 387M edges in the unfiltered version.\n\nUsage:\n    python generate_filtered_go.py --k 20 --output_path /path/to/go_filtered.csv\n"""\n\nimport os\nimport sys\nimport argparse\nimport pickle\nimport numpy as np\nimport pandas as pd\nimport scanpy as sc\nfrom scipy import sparse\nfrom tqdm import tqdm\n\n\ndef parse_args():\n    parser = argparse.ArgumentParser(description=\'Generate filtered GO graph\')\n    parser.add_argument(\'--data_path\', type=str,\n                        default=\'<ENV_ROOT>/nvme/model3/CellFM/gears_data/nocap_perturbation/perturb_processed.h5ad\',\n                        help=\'Path to perturb_processed.h5ad\')\n    parser.add_argument(\'--gene2go_path\', type=str,\n                        default=\'<ENV_ROOT>/nvme/model3/CellFM/gears_data/gene2go.pkl\',\n                        help=\'Path to gene2go.pkl\')\n    parser.add_argument(\'--output_path\', type=str,\n                        default=\'<ENV_ROOT>/nvme/model3/CellFM/gears_data/nocap_perturbation/go_filtered.csv\',\n                        help=\'Output path for filtered go.csv\')\n    parser.add_argument(\'--k\', type=int, default=107,\n                        help=\'Top-k neighbors to keep per gene (default: 107, matches Norman density)\')\n    parser.add_argument(\'--threshold\', type=float, default=0.1,\n                        help=\'Minimum Jaccard similarity threshold (default: 0.1)\')\n    return parser.parse_args()\n\n\ndef compute_jaccard_all(gene2go, all_gene_names, threshold=0.1, use_topk=False, k=20):\n    """\n    Compute Jaccard similarity and keep ALL edges above threshold (like Norman).\n    Also ensures ALL genes from the dataset are included (with self-loops for genes without GO).\n\n    Args:\n        gene2go: dict mapping gene name -> list of GO terms\n        all_gene_names: list of ALL gene names to include (from perturb_processed.h5ad)\n        threshold: minimum Jaccard similarity (default: 0.1)\n        use_topk: if True, use top-k filtering; if False, keep all above threshold\n        k: number of top neighbors (only used if use_topk=True)\n\n    Returns:\n        DataFrame with columns: source, target, importance\n    """\n    # Separate genes with and without GO annotations\n    genes_with_go = [g for g in all_gene_names if g in gene2go]\n    genes_without_go = [g for g in all_gene_names if g not in gene2go]\n\n    print(f"Total genes in dataset: {len(all_gene_names)}")\n    print(f"Genes WITH GO annotations: {len(genes_with_go)}")\n    print(f"Genes WITHOUT GO annotations: {len(genes_without_go)}")\n\n    # Build gene2go for genes with annotations\n    gene2go_filtered = {g: gene2go[g] for g in genes_with_go}\n\n    if len(gene2go_filtered) == 0:\n        print("WARNING: No genes found in gene2go.pkl!")\n        # Return just self-loops for all genes\n        edge_list = [(g, g, 1.0) for g in all_gene_names]\n        return pd.DataFrame(edge_list, columns=[\'source\', \'target\', \'importance\'])\n\n    # Get all unique GO terms\n    all_go_terms = set()\n    for terms in gene2go_filtered.values():\n        all_go_terms.update(terms)\n\n    go_term_to_idx = {term: idx for idx, term in enumerate(all_go_terms)}\n    filtered_gene_names = list(gene2go_filtered.keys())\n    gene_to_idx = {gene: idx for idx, gene in enumerate(filtered_gene_names)}\n\n    print(f"Total GO terms: {len(all_go_terms)}")\n    print(f"Building sparse GO matrix...")\n\n    # Build sparse binary matrix: genes x GO terms\n    rows, cols = [], []\n    for gene, terms in gene2go_filtered.items():\n        gene_idx = gene_to_idx[gene]\n        for term in terms:\n            rows.append(gene_idx)\n            cols.append(go_term_to_idx[term])\n\n    n_genes = len(filtered_gene_names)\n    n_terms = len(all_go_terms)\n    go_matrix = sparse.csr_matrix(\n        (np.ones(len(rows)), (rows, cols)),\n        shape=(n_genes, n_terms),\n        dtype=np.float32\n    )\n\n    # Compute intersection matrix\n    print("Computing intersection matrix...")\n    intersection = go_matrix @ go_matrix.T\n\n    # Row sums (set sizes)\n    set_sizes = np.array(go_matrix.sum(axis=1)).flatten()\n\n    # Convert to dense (feasible for ~19K genes, needs ~1.4GB RAM)\n    print("Converting to dense matrix...")\n    intersection_dense = intersection.toarray()\n\n    # Compute Jaccard: intersection / union\n    print("Computing Jaccard similarities...")\n    union_matrix = set_sizes[:, np.newaxis] + set_sizes[np.newaxis, :] - intersection_dense\n\n    # Avoid division by zero\n    union_matrix[union_matrix == 0] = 1\n    jaccard_matrix = intersection_dense / union_matrix\n\n    # Set diagonal to 0 (will add self-loops separately)\n    np.fill_diagonal(jaccard_matrix, 0)\n\n    # Collect edges\n    edge_list = []\n\n    if use_topk:\n        # Top-k approach (original)\n        print(f"Selecting top-{k} neighbors per gene...")\n        for i in tqdm(range(n_genes), desc="Processing genes"):\n            gene_i = filtered_gene_names[i]\n            similarities = jaccard_matrix[i, :]\n\n            # Get top-k indices\n            top_indices = np.argsort(similarities)[::-1][:k]\n\n            for j in top_indices:\n                if similarities[j] >= threshold:\n                    gene_j = filtered_gene_names[j]\n                    edge_list.append((gene_i, gene_j, similarities[j]))\n                    edge_list.append((gene_j, gene_i, similarities[j]))\n    else:\n        # Keep ALL edges above threshold (like Norman)\n        print(f"Keeping ALL edges with Jaccard >= {threshold}...")\n        # Get upper triangle indices where jaccard >= threshold\n        above_threshold = np.where((jaccard_matrix >= threshold) & (np.triu(np.ones_like(jaccard_matrix), k=1) == 1))\n\n        print(f"Found {len(above_threshold[0]):,} unique pairs above threshold")\n\n        for idx in tqdm(range(len(above_threshold[0])), desc="Building edge list"):\n            i, j = above_threshold[0][idx], above_threshold[1][idx]\n            gene_i = filtered_gene_names[i]\n            gene_j = filtered_gene_names[j]\n            jaccard = jaccard_matrix[i, j]\n            # Bidirectional edges\n            edge_list.append((gene_i, gene_j, jaccard))\n            edge_list.append((gene_j, gene_i, jaccard))\n\n    # Add self-loops for ALL genes (including those without GO)\n    print(f"Adding self-loops for all {len(all_gene_names)} genes...")\n    for gene in all_gene_names:\n        edge_list.append((gene, gene, 1.0))\n\n    # Create DataFrame and remove duplicates\n    print("Creating DataFrame and removing duplicates...")\n    df = pd.DataFrame(edge_list, columns=[\'source\', \'target\', \'importance\'])\n    df = df.drop_duplicates()\n\n    return df\n\n\ndef main():\n    args = parse_args()\n\n    print("=" * 70)\n    print("Generating Filtered GO Graph")\n    print("=" * 70)\n    print(f"Data path: {args.data_path}")\n    print(f"Gene2GO path: {args.gene2go_path}")\n    print(f"Output path: {args.output_path}")\n    print(f"Top-k: {args.k}")\n    print(f"Threshold: {args.threshold}")\n    print("=" * 70)\n\n    # Load perturb_processed.h5ad to get gene names\n    print("\\n[1/3] Loading gene names from perturb_processed.h5ad...")\n    adata = sc.read_h5ad(args.data_path)\n\n    # Get gene names from var\n    if \'gene_name\' in adata.var.columns:\n        gene_names = adata.var[\'gene_name\'].tolist()\n    else:\n        gene_names = adata.var_names.tolist()\n\n    print(f"Total genes in dataset: {len(gene_names)}")\n    print(f"Sample genes: {gene_names[:10]}")\n\n    # Load gene2go.pkl\n    print("\\n[2/3] Loading gene2go.pkl...")\n    with open(args.gene2go_path, \'rb\') as f:\n        gene2go = pickle.load(f)\n    print(f"Total genes in gene2go: {len(gene2go)}")\n\n    # Compute filtered GO graph\n    print("\\n[3/3] Computing filtered GO graph...")\n    # Use top-k filtering to match Norman\'s edge density (~215 edges/gene)\n    df_go = compute_jaccard_all(gene2go, gene_names, threshold=args.threshold, use_topk=True, k=args.k)\n\n    # Save\n    print(f"\\nSaving to {args.output_path}...")\n    df_go.to_csv(args.output_path, index=False)\n\n    # Print statistics\n    print("\\n" + "=" * 70)\n    print("RESULTS")\n    print("=" * 70)\n    print(f"Total edges: {len(df_go):,}")\n    print(f"Unique genes: {len(set(df_go[\'source\']) | set(df_go[\'target\'])):,}")\n    print(f"Self-loops: {len(df_go[df_go[\'source\'] == df_go[\'target\']]):,}")\n    print(f"File size: {os.path.getsize(args.output_path) / 1024 / 1024:.2f} MB")\n\n    print("\\nImportance distribution:")\n    print(df_go[\'importance\'].describe())\n\n    print("\\nSample edges:")\n    print(df_go.head(10))\n\n    # Compare with original\n    original_path = args.output_path.replace(\'_filtered\', \'\')\n    if os.path.exists(original_path) and original_path != args.output_path:\n        original_size = os.path.getsize(original_path)\n        new_size = os.path.getsize(args.output_path)\n        print(f"\\nComparison with original:")\n        print(f"  Original: {original_size / 1024 / 1024 / 1024:.2f} GB")\n        print(f"  Filtered: {new_size / 1024 / 1024:.2f} MB")\n        print(f"  Reduction: {original_size / new_size:.0f}x smaller")\n\n    print("\\nDone!")\n\n\nif __name__ == \'__main__\':\n    main()\n', 'train': '"""\n01_train_gears.py - Train GEARS with Cell-Level Embeddings (Original CellFM Approach)\n\nThis script follows the ORIGINAL CellFM approach:\n1. Load pre-extracted cell-level embeddings from 00_extract_ctrl_embeddings.py\n2. Use the modified GEARS model that looks up embeddings by cell index (data.z)\n3. Train GEARS for perturbation prediction\n\nThis CellFM-GEARS workflow uses cell-level embeddings, with a unique gene-embedding matrix for each sampled control cell.\n\nUsage:\n    python 01_train_gears.py \\\n        --data_dir /path/to/data \\\n        --data_name norman \\\n        --emb_path embeddings/cellfm_ctrl_emb.npy \\\n        --output_dir results/cellfm \\\n        --seed 1 \\\n        --epochs 15 \\\n        --device cuda:0\n"""\n\nimport os\nimport sys\nimport argparse\nimport numpy as np\nimport torch\nimport pickle\nfrom datetime import datetime\n\n# Add parent directory to path\nCODES_DIR = os.path.dirname(os.path.abspath(__file__))\nROOT_DIR = os.path.dirname(CODES_DIR)\nsys.path.insert(0, ROOT_DIR)\nsys.path.insert(0, CODES_DIR)\n\nfrom gears import PertData\nfrom cellfm_gears_model import GEARS_Model_CellEmb, load_cell_embeddings\n\n\ndef parse_args():\n    parser = argparse.ArgumentParser(description=\'Train GEARS with Cell-Level Embeddings\')\n\n    # Data paths\n    parser.add_argument(\'--data_dir\', type=str, required=True,\n                        help=\'Directory containing GEARS data\')\n    parser.add_argument(\'--data_name\', type=str, required=True,\n                        help=\'Dataset name (e.g., norman, adamson)\')\n    parser.add_argument(\'--emb_path\', type=str, required=True,\n                        help=\'Path to cell-level embeddings (.npy file)\')\n    parser.add_argument(\'--output_dir\', type=str, required=True,\n                        help=\'Output directory for results\')\n\n    # Training parameters\n    parser.add_argument(\'--seed\', type=int, default=1,\n                        help=\'Random seed (default: 1)\')\n    parser.add_argument(\'--epochs\', type=int, default=15,\n                        help=\'Number of epochs (default: 15)\')\n    parser.add_argument(\'--batch_size\', type=int, default=10,\n                        help=\'Training batch size (default: 10)\')\n    parser.add_argument(\'--test_batch_size\', type=int, default=32,\n                        help=\'Test batch size (default: 32)\')\n    parser.add_argument(\'--lr\', type=float, default=0.005,\n                        help=\'Learning rate (default: 0.005)\')\n    parser.add_argument(\'--weight_decay\', type=float, default=1e-5,\n                        help=\'Weight decay (default: 1e-5)\')\n\n    # Model parameters\n    parser.add_argument(\'--hidden_size\', type=int, default=512,\n                        help=\'Hidden size (default: 512)\')\n    parser.add_argument(\'--accumulation_steps\', type=int, default=5,\n                        help=\'Gradient accumulation steps (default: 5)\')\n\n    # Split parameters\n    parser.add_argument(\'--split\', type=str, default=\'simulation\',\n                        help=\'Split type (default: simulation)\')\n    parser.add_argument(\'--train_gene_set_size\', type=float, default=0.75,\n                        help=\'Train gene set size (default: 0.75)\')\n\n    # Device\n    parser.add_argument(\'--device\', type=str, default=\'cuda:0\',\n                        help=\'Device to use (default: cuda:0)\')\n\n    # Memory optimization\n    parser.add_argument(\'--max_cells\', type=int, default=None,\n                        help=\'Maximum number of cells to use from embeddings (default: use all)\')\n\n    return parser.parse_args()\n\n\ndef setup_gears_args(pert_data, hidden_size, device, data_dir, data_name, use_minimal_go=False):\n    """Setup arguments for GEARS model initialization."""\n    import pandas as pd\n    import pickle as pkl\n\n    # Use the full dataset path (data_dir/data_name) instead of pert_data.data_path\n    # because pert_data.data_path only contains the base directory\n    dataset_path = os.path.join(data_dir, data_name)\n    print(f"  Dataset path: {dataset_path}")\n\n    # Get perturbation names from gene2go.pkl first\n    gene2go_path = os.path.join(data_dir, \'gene2go.pkl\')\n    print(f"  Loading perturbation names from {gene2go_path}...")\n    with open(gene2go_path, \'rb\') as f:\n        gene2go = pkl.load(f)\n    pert_names = list(gene2go.keys())\n    num_perts = len(pert_names)\n    print(f"  Number of perturbations: {num_perts:,}")\n\n    if use_minimal_go:\n        # Use minimal GO graph (self-loops only) to save memory\n        # The filtered go.csv has 3.1M edges (k=107, Norman-like density)\n        print(f"  Using minimal GO graph (self-loops only) for memory efficiency")\n        G_go = torch.LongTensor([[i, i] for i in range(num_perts)]).T\n        G_go_weight = torch.ones(num_perts)\n    else:\n        # Load pre-computed GO graph from go.csv (MUCH faster than rebuilding)\n        go_path = os.path.join(dataset_path, \'go.csv\')\n        if os.path.exists(go_path):\n            print(f"  Loading pre-computed GO graph from {go_path}...")\n            go_df = pd.read_csv(go_path)\n            go_df = go_df.dropna()\n            print(f"  GO graph edges: {len(go_df):,}")\n\n            # IMPORTANT: Map GO graph edges to indices in the FULL pert_names list (gene2go.pkl)\n            # Do NOT overwrite pert_names - it must stay as gene2go.pkl\'s 67,832 genes\n            # because training data uses perturbation indices from gene2go.pkl\n            gene_to_idx = {gene: idx for idx, gene in enumerate(pert_names)}\n\n            # Filter edges to only include genes that exist in pert_names\n            valid_edges = []\n            valid_weights = []\n            skipped = 0\n            for i, row in go_df.iterrows():\n                src, tgt = row[\'source\'], row[\'target\']\n                if src in gene_to_idx and tgt in gene_to_idx:\n                    valid_edges.append([gene_to_idx[src], gene_to_idx[tgt]])\n                    valid_weights.append(row[\'importance\'])\n                else:\n                    skipped += 1\n\n            if skipped > 0:\n                print(f"  Skipped {skipped:,} edges (genes not in gene2go.pkl)")\n            print(f"  Valid GO graph edges: {len(valid_edges):,}")\n\n            if len(valid_edges) > 0:\n                G_go = torch.LongTensor(valid_edges).T\n                G_go_weight = torch.FloatTensor(valid_weights)\n            else:\n                print(f"  No valid edges found, using self-loops...")\n                G_go = torch.LongTensor([[i, i] for i in range(num_perts)]).T\n                G_go_weight = torch.ones(num_perts)\n        else:\n            print(f"  go.csv not found at {go_path}, using self-loops...")\n            G_go = torch.LongTensor([[i, i] for i in range(num_perts)]).T\n            G_go_weight = torch.ones(num_perts)\n\n    # Gene co-expression graph (simple version - identity)\n    num_genes = pert_data.adata.n_vars\n    # Use simple self-loops for co-expression (can be improved with actual co-expression data)\n    G_coexpress = torch.LongTensor([[i, i] for i in range(num_genes)]).T\n    G_coexpress_weight = torch.ones(num_genes)\n\n    args = {\n        \'num_genes\': num_genes,\n        \'num_perts\': len(pert_names),\n        \'hidden_size\': hidden_size,\n        \'uncertainty\': False,\n        \'num_go_gnn_layers\': 2,\n        \'decoder_hidden_size\': hidden_size,\n        \'num_gene_gnn_layers\': 2,\n        \'no_perturb\': False,\n        \'cell_fitness_pred\': False,\n        \'G_go\': G_go,\n        \'G_go_weight\': G_go_weight,\n        \'G_coexpress\': G_coexpress,\n        \'G_coexpress_weight\': G_coexpress_weight,\n        \'device\': device,\n        \'model_type\': \'emb\',\n    }\n\n    return args\n\n\ndef train_epoch(model, train_loader, optimizer, device, accumulation_steps=1):\n    """Train for one epoch."""\n    model.train()\n    total_loss = 0\n    num_batches = 0\n\n    optimizer.zero_grad()\n\n    for i, batch in enumerate(train_loader):\n        batch = batch.to(device)\n        pred = model(batch)\n        y = batch.y\n\n        # MSE loss\n        loss = torch.nn.functional.mse_loss(pred, y)\n\n        # Gradient accumulation\n        loss = loss / accumulation_steps\n        loss.backward()\n\n        if (i + 1) % accumulation_steps == 0:\n            optimizer.step()\n            optimizer.zero_grad()\n\n        total_loss += loss.item() * accumulation_steps\n        num_batches += 1\n\n    return total_loss / num_batches\n\n\ndef evaluate(model, data_loader, device):\n    """Evaluate model on data loader."""\n    model.eval()\n    total_loss = 0\n    num_batches = 0\n\n    with torch.no_grad():\n        for batch in data_loader:\n            batch = batch.to(device)\n            pred = model(batch)\n            y = batch.y\n\n            loss = torch.nn.functional.mse_loss(pred, y)\n            total_loss += loss.item()\n            num_batches += 1\n\n    return total_loss / num_batches\n\n\ndef main():\n    args = parse_args()\n\n    print("=" * 70)\n    print("GEARS Training with Cell-Level Embeddings (Original CellFM Approach)")\n    print("=" * 70)\n    print(f"Data directory: {args.data_dir}")\n    print(f"Dataset: {args.data_name}")\n    print(f"Embedding path: {args.emb_path}")\n    print(f"Output directory: {args.output_dir}")\n    print(f"Seed: {args.seed}")\n    print(f"Epochs: {args.epochs}")\n    print(f"Device: {args.device}")\n    print("=" * 70)\n\n    # Create output directory\n    os.makedirs(args.output_dir, exist_ok=True)\n\n    # Set random seeds\n    np.random.seed(args.seed)\n    torch.manual_seed(args.seed)\n    if torch.cuda.is_available():\n        torch.cuda.manual_seed(args.seed)\n\n    # Setup device\n    device = torch.device(args.device if torch.cuda.is_available() else \'cpu\')\n    print(f"\\nUsing device: {device}")\n\n    # Load data\n    print("\\n[1/5] Loading perturbation data...")\n    pert_data = PertData(args.data_dir)\n    pert_data.load(data_path=os.path.join(args.data_dir, args.data_name))\n    pert_data.prepare_split(\n        split=args.split,\n        seed=args.seed,\n        train_gene_set_size=args.train_gene_set_size\n    )\n    pert_data.get_dataloader(\n        batch_size=args.batch_size,\n        test_batch_size=args.test_batch_size\n    )\n\n    print(f"  Total genes: {pert_data.adata.n_vars}")\n    print(f"  Total cells: {pert_data.adata.n_obs}")\n\n    # Load cell-level embeddings\n    print("\\n[2/5] Loading cell-level embeddings...")\n    ctrl_emb = load_cell_embeddings(args.emb_path, device=device, max_cells=args.max_cells)\n\n    # Verify embedding dimensions match\n    n_genes_data = pert_data.adata.n_vars\n    n_genes_emb = ctrl_emb.shape[1]\n    if n_genes_data != n_genes_emb:\n        print(f"  WARNING: Gene count mismatch!")\n        print(f"    Data: {n_genes_data}, Embeddings: {n_genes_emb}")\n        print(f"    Using min: {min(n_genes_data, n_genes_emb)}")\n\n    # Setup model arguments\n    print("\\n[3/5] Initializing GEARS model...")\n    model_args = setup_gears_args(pert_data, args.hidden_size, device, args.data_dir, args.data_name)\n\n    # Create model\n    model = GEARS_Model_CellEmb(model_args, ctrl_emb=ctrl_emb)\n    model = model.to(device)\n\n    # Count parameters\n    total_params = sum(p.numel() for p in model.parameters())\n    trainable_params = sum(p.numel() for p in model.parameters() if p.requires_grad)\n    print(f"  Total parameters: {total_params:,}")\n    print(f"  Trainable parameters: {trainable_params:,}")\n\n    # Setup optimizer\n    optimizer = torch.optim.Adam(\n        model.parameters(),\n        lr=args.lr,\n        weight_decay=args.weight_decay\n    )\n\n    # Get dataloaders\n    train_loader = pert_data.dataloader[\'train_loader\']\n    val_loader = pert_data.dataloader[\'val_loader\']\n    test_loader = pert_data.dataloader.get(\'test_loader\', None)\n\n    print(f"  Train batches: {len(train_loader)}")\n    print(f"  Val batches: {len(val_loader)}")\n    if test_loader:\n        print(f"  Test batches: {len(test_loader)}")\n\n    # Training loop\n    print("\\n[4/5] Training...")\n    best_val_loss = float(\'inf\')\n    best_epoch = 0\n    train_losses = []\n    val_losses = []\n\n    log_file = os.path.join(args.output_dir, \'training_log.txt\')\n    with open(log_file, \'w\') as f:\n        f.write(f"Training started at {datetime.now()}\\n")\n        f.write(f"Args: {vars(args)}\\n\\n")\n\n    for epoch in range(1, args.epochs + 1):\n        train_loss = train_epoch(\n            model, train_loader, optimizer, device,\n            accumulation_steps=args.accumulation_steps\n        )\n        val_loss = evaluate(model, val_loader, device)\n\n        train_losses.append(train_loss)\n        val_losses.append(val_loss)\n\n        log_msg = f"Epoch {epoch:3d}/{args.epochs}: Train Loss = {train_loss:.6f}, Val Loss = {val_loss:.6f}"\n\n        if val_loss < best_val_loss:\n            best_val_loss = val_loss\n            best_epoch = epoch\n            # Save best model\n            torch.save(model.state_dict(), os.path.join(args.output_dir, \'best_model.pt\'))\n            log_msg += " *"\n\n        print(log_msg)\n        with open(log_file, \'a\') as f:\n            f.write(log_msg + \'\\n\')\n\n    # Save final model\n    torch.save(model.state_dict(), os.path.join(args.output_dir, \'final_model.pt\'))\n\n    # Evaluate on test set\n    print("\\n[5/5] Final Evaluation...")\n    if test_loader:\n        # Load best model for evaluation (use map_location to avoid OOM)\n        checkpoint = torch.load(os.path.join(args.output_dir, \'best_model.pt\'), map_location=\'cpu\')\n        model.load_state_dict(checkpoint)\n        del checkpoint\n        model = model.to(device)\n        test_loss = evaluate(model, test_loader, device)\n        print(f"  Test Loss (best model, epoch {best_epoch}): {test_loss:.6f}")\n    else:\n        test_loss = None\n\n    # Save training history\n    history = {\n        \'train_losses\': train_losses,\n        \'val_losses\': val_losses,\n        \'best_epoch\': best_epoch,\n        \'best_val_loss\': best_val_loss,\n        \'test_loss\': test_loss,\n        \'args\': vars(args)\n    }\n    with open(os.path.join(args.output_dir, \'training_history.pkl\'), \'wb\') as f:\n        pickle.dump(history, f)\n\n    print("\\n" + "=" * 70)\n    print("Training Complete!")\n    print("=" * 70)\n    print(f"Best epoch: {best_epoch}")\n    print(f"Best val loss: {best_val_loss:.6f}")\n    if test_loss:\n        print(f"Test loss: {test_loss:.6f}")\n    print(f"Results saved to: {args.output_dir}")\n\n\nif __name__ == \'__main__\':\n    main()\n'}


def run_embedded_stage(stage_name, argv):
    source = STAGE_SOURCES[stage_name]
    filename = f"<CellFM {stage_name} stage>"
    namespace = {'__name__': '__embedded_stage__', '__file__': filename}
    old_argv = sys.argv[:]
    try:
        sys.argv = [filename] + list(argv)
        exec(compile(source, filename, 'exec'), namespace)
        namespace['main']()
    finally:
        sys.argv = old_argv


def main():
    parser = argparse.ArgumentParser(description='Prepare inputs and train CellFM for NOCAP benchmarking')
    parser.add_argument('--skip_adapt_checkpoint', action='store_true')
    parser.add_argument('--skip_extract_embeddings', action='store_true')
    parser.add_argument('--skip_go_graph', action='store_true')
    parser.add_argument('--skip_train', action='store_true')
    parser.add_argument('--data_path', required=True, help='Input h5ad path')
    parser.add_argument('--cellfm_ckpt_path', required=True, help='Original or adapted CellFM checkpoint path')
    parser.add_argument('--adapted_ckpt_dir', required=True, help='Output directory for adapted CellFM checkpoint')
    parser.add_argument('--embedding_output_path', required=True, help='Output .npy path for control embeddings')
    parser.add_argument('--gene2go_path', required=True, help='gene2go.pkl path')
    parser.add_argument('--go_output_path', required=True, help='Filtered GO graph output CSV')
    parser.add_argument('--gears_data_dir', required=True, help='GEARS data directory')
    parser.add_argument('--gears_data_name', required=True, help='GEARS data name')
    parser.add_argument('--output_dir', required=True, help='CellFM training output directory')
    parser.add_argument('--seed', type=int, default=1)
    parser.add_argument('--epochs', type=int, default=15)
    parser.add_argument('--batch_size', type=int, default=10)
    parser.add_argument('--adapt_epochs', type=int, default=5)
    parser.add_argument('--adapt_batch_size', type=int, default=4)
    parser.add_argument('--embedding_batch_size', type=int, default=32)
    parser.add_argument('--device', default='cuda:0')
    parser.add_argument('--max_cells', type=int, default=None)
    args = parser.parse_args()

    adapted_ckpt = args.cellfm_ckpt_path
    if not args.skip_adapt_checkpoint:
        run_embedded_stage('adapt_checkpoint', [
            '--data_path', args.data_path,
            '--ckpt_path', args.cellfm_ckpt_path,
            '--output_dir', args.adapted_ckpt_dir,
            '--epochs', str(args.adapt_epochs),
            '--batch_size', str(args.adapt_batch_size),
            '--device', args.device,
            '--seed', str(args.seed),
        ])
        adapted_ckpt = args.adapted_ckpt_dir.rstrip('/') + '/best_checkpoint.pth'

    if not args.skip_extract_embeddings:
        emb_args = [
            '--data_path', args.data_path,
            '--ckpt_path', adapted_ckpt,
            '--output_path', args.embedding_output_path,
            '--batch_size', str(args.embedding_batch_size),
            '--device', args.device,
            '--seed', str(args.seed),
        ]
        if args.max_cells is not None:
            emb_args += ['--max_cells', str(args.max_cells)]
        run_embedded_stage('extract_embeddings', emb_args)

    if not args.skip_go_graph:
        run_embedded_stage('generate_go_graph', [
            '--data_path', args.data_path,
            '--gene2go_path', args.gene2go_path,
            '--output_path', args.go_output_path,
        ])

    if not args.skip_train:
        train_args = [
            '--data_dir', args.gears_data_dir,
            '--data_name', args.gears_data_name,
            '--emb_path', args.embedding_output_path,
            '--output_dir', args.output_dir,
            '--seed', str(args.seed),
            '--epochs', str(args.epochs),
            '--batch_size', str(args.batch_size),
            '--device', args.device,
        ]
        if args.max_cells is not None:
            train_args += ['--max_cells', str(args.max_cells)]
        run_embedded_stage('train', train_args)


if __name__ == '__main__':
    main()
